  auto _NAME = _fbb.CreateString(_o->NAME);
  auto _DESCRIPTION = _o->DESCRIPTION.empty() ? 0 : _fbb.CreateString(_o->DESCRIPTION);
  auto _TAGS = _o->TAGS.size() ? _fbb.CreateVectorOfStrings(_o->TAGS) : 0;
  auto _MEMBERSHIP_MODE = _o->MEMBERSHIP_MODE;
  auto _MEMBERS = _o->MEMBERS.size() ? _fbb.CreateVector<::flatbuffers::Offset<EGPMember>> (_o->MEMBERS.size(), [](size_t i, _VectorArgs *__va) { return CreateEGPMember(*__va->__fbb, __va->__o->MEMBERS[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _QUERY = _o->QUERY ? CreateEGPQuery(_fbb, _o->QUERY.get(), _rehasher) : 0;
  auto _CREATED_AT = _o->CREATED_AT.empty() ? 0 : _fbb.CreateString(_o->CREATED_AT);
  auto _UPDATED_AT = _fbb.CreateString(_o->UPDATED_AT);
  auto _PROVENANCE = _o->PROVENANCE.size() ? _fbb.CreateVector<::flatbuffers::Offset<EGPProvenance>> (_o->PROVENANCE.size(), [](size_t i, _VectorArgs *__va) { return CreateEGPProvenance(*__va->__fbb, __va->__o->PROVENANCE[i].get(), __va->__rehasher); }, &_va ) : 0;
