inline const EGP *GetEGP(const void *buf) {
  return ::flatbuffers::GetRoot<EGP>(buf);
}

inline const EGP *GetSizePrefixedEGP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<EGP>(buf);
}

inline const char *EGPIdentifier() {
  return "$EGP";
}

inline bool EGPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, EGPIdentifier());
}

inline bool SizePrefixedEGPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, EGPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyEGPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<EGP>(EGPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedEGPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<EGP>(EGPIdentifier());
}

inline void FinishEGPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<EGP> root) {
  fbb.Finish(root, EGPIdentifier());
}

inline void FinishSizePrefixedEGPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<EGP> root) {
  fbb.FinishSizePrefixed(root, EGPIdentifier());
}

inline std::unique_ptr<EGPT> UnPackEGP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<EGPT>(GetEGP(buf)->UnPack(res));
}

inline std::unique_ptr<EGPT> UnPackSizePrefixedEGP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<EGPT>(GetSizePrefixedEGP(buf)->UnPack(res));
}

